      {/* ------------------------------------------------------------------ */}
      {/* STEP 2 — File upload                                                */}
      {/* ------------------------------------------------------------------ */}
      {step === 2 && (
        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6 space-y-5">
