                    </p>
                    <p className="mt-1 text-xs text-slate-500">
                      APK · AAB · IPA — {t('حتى 100 MB', '100 Mo maximum', 'up to 100 MB')}
                    </p>
                  </div>
                </>
              )}
              <input
                ref={fileInputRef}
