          <Link href="/admob" className="hover:text-white transition-colors">
            {lang === 'ar' ? 'إعداد AdMob' : lang === 'fr' ? 'Config. AdMob' : 'AdMob Setup'}
          </Link>
          <Link href="/contact" className="hover:text-white transition-colors">
            {t('navContact')}
