          {user && (
            <Link href="/dashboard" className="text-indigo-400 hover:text-indigo-300 font-semibold flex items-center gap-1.5">
              <LayoutDashboard className="h-4 w-4" />
              <span>{lang === 'ar' ? 'تطبيقاتي' : 'Dashboard'}</span>
